// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 seq_,
        bytes32 batcher_,
        uint256 overhead_,
        uint256 scalar_,
        address caller_
    ) public {
        vm.assume(caller_ != address(0)); // depositorAccount defaults to 0, so any other caller passes the require
        vm.prank(caller_);
        bool ok;
        try c.setL1BlockValues(number_, timestamp_, basefee_, hash_, seq_, batcher_, overhead_, scalar_) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok ? (c.l1FeeScalar() == 0 && scalar_ != 0 ? false : true) : true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(
        address actor,
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        vm.prank(actor);
        c.setL1BlockValues(
            _number, _timestamp, _basefee, _hash,
            _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar
        );
        assertTrue(c.l1FeeScalar() == 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) external {
        bool ok = true;
        bytes memory ret;
        (ok, ret) = address(c).call(
            abi.encodeWithSelector(
                c.setL1BlockValues.selector,
                _number, _timestamp, _basefee, _hash,
                _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar
            )
        );
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function runTest(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        require(msg.sender != c.depositorAccount());
        c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        );
        assert(c.depositorAccount() == msg.sender);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "setL1BlockValues(uint64,uint64,uint256,bytes32,uint64,bytes32,uint256,uint256)",
                _number,
                _timestamp,
                _basefee,
                _hash,
                _sequenceNumber,
                _batcherHash,
                _l1FeeOverhead,
                _l1FeeScalar
            )
        );
        assert(!ok || msg.sender == c.depositorAccount());
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test() public {
        // P requires msg.sender == depositorAccount (initially address(0)),
        // which no live contract caller can equal, so the call must revert.
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.setL1BlockValues.selector,
                uint64(1),
                uint64(2),
                uint256(3),
                bytes32(0),
                uint64(4),
                bytes32(0),
                uint256(5),
                uint256(6)
            )
        );
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(/* params */) public payable {
        require(address(this) != c.depositorAccount());
        bool reverted; try c.setL1BlockValues(1, 2, 3, bytes32(0), 4, bytes32(0), 5, 6) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}
